#!/usr/bin/env python3
from pathlib import Path
import base64,zlib,shutil,subprocess,sys
from datetime import datetime

PAYLOADS={}
PAYLOADS['app/dashboard/ui.tsx']=""""""
PAYLOADS['components/sidebar.tsx']=""""""
PAYLOADS['components/mobile-nav.tsx']=""""""
PAYLOADS['components/av-logo.tsx']=""""""
PAYLOADS['app/page.tsx']=""""""
PAYLOADS['app/layout.tsx']="""eNpFTj1rwzAQ3fUrDk0tFHl3HEPp0KWUkkL3y+kcCyRdkE5QE/zfG3tolsfjffFCukpRsK67RDljrI5qtQdj+Hc3SHJVSKzoUfF4MwAaNHJvX3/gfUkZqwaq9uVueK5UwlWD5N6+CdLs4Jtm9i2ygy8uk5Tk7tH1se95whYVppZpK8JJRD9wkaZPN5pD9IXz2v/T/sRI6nb8FM/r83apsLaSYZg1RYiYL0fL2Y7DWfwyPmaGbheGbsuNB7OaPzjyWRI="""
PAYLOADS['app/icon.svg']=""""""
CSS=""""""
START="/* AV_V3_IDENTITY_START */";END="/* AV_V3_IDENTITY_END */"
def unpack(v): return zlib.decompress(base64.b64decode(v))

root=Path.cwd()
if not (root/"package.json").exists():
    print("Run this from the coach-hours-v1 project root (same folder as package.json).");sys.exit(1)

stamp=datetime.now().strftime("%Y%m%d-%H%M%S")
backup=root/".av-backups"/f"pre-v3.1.0-{stamp}"
for rel in list(PAYLOADS.keys())+["app/globals.css"]:
    src=root/rel
    if src.exists():
        dst=backup/rel;dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(src,dst)
print("Backup:",backup)

for rel,data in PAYLOADS.items():
    dst=root/rel;dst.parent.mkdir(parents=True,exist_ok=True);dst.write_bytes(unpack(data))

cp=root/"app/globals.css";existing=cp.read_text(encoding="utf-8")
if START in existing and END in existing:
    existing=existing.split(START,1)[0].rstrip()+"\n\n"+existing.split(END,1)[1].lstrip()
cp.write_text(existing.rstrip()+"\n\n"+START+"\n"+unpack(CSS).decode("utf-8").strip()+"\n"+END+"\n",encoding="utf-8")

print("Installed AV Gymnastics v3.1.0 Coach Schedule Polish.")
print("Running production build...")
r=subprocess.run(["npm","run","build"],cwd=root)
if r.returncode:
    print("BUILD FAILED. Nothing has been pushed.");print("Backup:",backup);sys.exit(r.returncode)
print("BUILD PASSED.")

if "--deploy" in sys.argv:
    subprocess.run(["git","add","app/dashboard/ui.tsx","app/globals.css","app/page.tsx","app/layout.tsx","app/icon.svg","components/sidebar.tsx","components/mobile-nav.tsx","components/av-logo.tsx"],cwd=root,check=True)
    d=subprocess.run(["git","diff","--cached","--quiet"],cwd=root)
    if d.returncode:
        subprocess.run(["git","commit","-m","Release AV Gymnastics v3.1.0 coach schedule polish"],cwd=root,check=True)
        subprocess.run(["git","push","origin","main"],cwd=root,check=True)
        print("Pushed to GitHub. Wait for Vercel Ready.")
    else: print("No changes to commit.")
